let S;

function setup() {
	S = ~~(max(windowWidth, windowHeight) / ~~random(4, 9));
  createCanvas(S*~~(windowWidth/S), S*~~(windowHeight/S)); // (S = max(windowWidth, windowHeight)), S
	background("rgb(2,2,8)");
	describe("grid of deltoid outlines in red/orange on dark background, some filled, slightly varying form");
  frameRate(60);
  noFill();
  strokeWeight(3);
	colorMode(HSB, 1);
  loop();
}

function draw() {
	blendMode(BLEND);
	background("rgb(2,2,8)")
	blendMode(ADD);

	const maxRot = 0.1;
  for (let y = S; y <= height - S; y += S) {
		for (let x = S; x <= width - S; x += S) {
			drawDeltoid(x, y, S)
		}
  }
}

function drawDeltoid(x, y, S) {
	push()
	translate(x, y);
	S *= 2
	const a = (noise(x, y, frameCount/123)-0.5) * 0.2;
	const f = noise(PI*x/y+TWO_PI, frameCount/231);
	const f1 = noise(x+y, frameCount/123) * 0.7 + 0.3;
	const f2 = noise(x*y, frameCount/123) * 0.4 + 0.2;
	const l1 = S * f1;
	const l2 = S * f2;
	const px = map(f, 0, 1, -l1, l1);
	rotate(a);
	const clr = color(fract(a+1), 0.75, 0.75);
	if (fract(a+1)<0.05) fill(clr)
	stroke(clr);
	beginShape();
	vertex(-l1/2, 0);
	vertex(px, -l2/2);
	vertex(l1/2, 0);
	vertex(px, l2/2);
	endShape(CLOSE);
	pop()
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
